(function(){
  let t = 0;
  const particles = [];
  const N = 70;
  for(let i=0;i<N;i++){
    particles.push({
      x: Math.random()*W(),
      y: Math.random()*H()+H(),
      speed: 0.12+Math.random()*0.3,
      phase: Math.random()*Math.PI*2,
      size: 1+Math.random()*2.0
    });
  }
  function flowerPath(x,y,size,rot,color,alpha){
    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    for(let i=0;i<5;i++){
      ctx.save();
      ctx.rotate((Math.PI*2/5)*i);
      ctx.beginPath();
      ctx.ellipse(0,-size*0.6,size*0.35,size*0.6,0,0,Math.PI*2);
      ctx.fillStyle = color;
      ctx.fill();
      ctx.restore();
    }
    ctx.beginPath();
    ctx.arc(0,0,size*0.22,0,Math.PI*2);
    ctx.fillStyle = '#f7e9b0';
    ctx.fill();
    ctx.restore();
  }
  const flowers = [
    {x:0.12,y:0.15,size:34,rotSpeed:0.05,phase:0},
    {x:0.88,y:0.85,size:40,rotSpeed:-0.04,phase:1.5},
    {x:0.87,y:0.16,size:20,rotSpeed:0.06,phase:3},
    {x:0.14,y:0.84,size:24,rotSpeed:-0.05,phase:4.2}
  ];
  function frame(){
    t += 0.008;
    const w = W(), h = H();
    const cx = w/2, cy = h/2;
    const minDim = Math.min(w,h);

    flowers.forEach(f=>{
      const fx = f.x*w, fy = f.y*h;
      const rot = Math.sin(t*f.rotSpeed*10+f.phase)*0.15;
      flowerPath(fx, fy, f.size, rot, PALETTE[1], 0.85);
    });

    for(let p of particles){
      p.y -= p.speed;
      p.x += Math.sin(t*2+p.phase)*0.4;
      if(p.y < -20){
        p.y = h + 20;
        p.x = Math.random()*w;
      }
      const dx = p.x-cx, dy = p.y-cy;
      const dist = Math.sqrt(dx*dx+dy*dy);
      const centerFade = Math.min(1, dist/(minDim*0.28));
      const pulse = 0.5+0.5*Math.sin(p.phase+t*3);
      const a = Math.max(0, Math.min(1, 0.25+0.5*pulse)) * centerFade;

      ctx.save();
      ctx.globalAlpha = a*0.8;
      const grad = ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.size*4);
      grad.addColorStop(0, PALETTE[2]);
      grad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.size*4,0,Math.PI*2);
      ctx.fill();

      ctx.globalAlpha = a;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.size,0,Math.PI*2);
      ctx.fillStyle = PALETTE[1];
      ctx.fill();
      ctx.restore();
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
